return [{ json: { raw: $json, config } }];

function digits(v) {
  return String(v || "").replace(/\D/g, "");
}

function txt(v) {
  return String(v || "").trim();
}

const raw = $json.raw || {};
const config = $json.config;

const incoming = {
  from: digits(raw.from || raw.body?.from || raw.payload?.from || raw.sender || raw.chatId || raw.key?.remoteJid),
  body: txt(raw.body?.body || raw.body?.text || raw.body || raw.text || raw.message || raw.payload?.body || raw.payload?.text || raw.message?.body),
  pushName: txt(raw.pushName || raw.body?.pushName || raw._data?.notifyName || raw.name || "")
};

return [{ json: { config, incoming } }];

const body = [{
  telefone: $json.incoming.from,
  nome: $json.incoming.pushName || "",
  updated_at: new Date().toISOString()
}];

return [{ json: { ...$json, supabase_body: body } }];

const previous = $item(0).$node["06 - Restaurar Contexto Pós-Upsert"].json;
const rows = Array.isArray($json) ? $json : [];
const cliente = rows[0] || {};

function normalizarTexto(v) {
  return String(v || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s\-\/]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function detectarCategoria(texto, config) {
  const alvo = normalizarTexto(texto);
  if (!alvo) return "";

  const categorias = config.categorias_veiculo || {};
  const ordemPrioridade = ["carga", "utilitarios", "caminhonete", "esportivos", "suv", "normais"];

  for (const codigo of ordemPrioridade) {
    const cat = categorias[codigo];
    if (!cat) continue;
    const palavras = cat.detector_palavras || [];
    for (const palavra of palavras) {
      const p = normalizarTexto(palavra);
      if (p && alvo.includes(p)) return codigo;
    }
  }

  return "";
}

const draft = {
  servico: cliente.draft_servico || "",
  veiculo: cliente.draft_veiculo || "",
  categoria_veiculo: detectarCategoria(cliente.draft_veiculo || "", previous.config),
  data_desejada: cliente.draft_data || "",
  hora_desejada: cliente.draft_hora || ""
};

return [{ json: { ...previous, cliente, draft } }];

const body = [{
  telefone: $json.incoming.from,
  nome: $json.incoming.pushName || "",
  direcao: "entrada",
  mensagem: $json.incoming.body,
  origem: "workflow_01_atendimento",
  created_at: new Date().toISOString()
}];

return [{ json: { ...$json, supabase_body: body } }];

const { config, incoming, draft } = $json;

function servicoCategoria(cat, servicoCodigo) {
  const base = config.servicos[servicoCodigo] || {};
  const custom = cat.servicos?.[servicoCodigo] || {};
  return { ...base, ...custom };
}

const categoriasAtivas = Object.entries(config.categorias_veiculo || {}).filter(([_, c]) => c.ativo);
const categoriasInativas = Object.entries(config.categorias_veiculo || {}).filter(([_, c]) => !c.ativo);

const categoriasTexto = categoriasAtivas.map(([codigo, c]) => {
  const simples = servicoCategoria(c, "simples");
  const detalhada = servicoCategoria(c, "detalhada");
  return `- ${codigo}: ${c.nome} | exemplos: ${c.exemplos}\n  simples: ${simples.preco_texto} | ${simples.tempo_texto}\n  detalhada: ${detalhada.preco_texto} | ${detalhada.tempo_texto}`;
}).join("\n");

const categoriasNaoAtendidasTexto = categoriasInativas.map(([codigo, c]) => `- ${codigo}: ${c.nome} | exemplos: ${c.exemplos}`).join("\n") || "Nenhuma";

const servicosTexto = Object.values(config.servicos)
  .map(s => `- ${s.codigo}: ${s.nome} | ${s.descricao}`)
  .join("\n");

const hoje = new Date().toLocaleDateString("pt-BR", { timeZone: config.atendimento.timezone });

const systemPrompt = `Você é um agente de atendimento para estética automotiva da empresa ${config.empresa.nome}, em ${config.empresa.cidade}.

Sua função é interpretar a mensagem do cliente e devolver APENAS JSON válido.

Serviços disponíveis:
${servicosTexto}

Categorias de veículo ATENDIDAS e preços por serviço:
${categoriasTexto}

Categorias NÃO atendidas:
${categoriasNaoAtendidasTexto}

Data de hoje: ${hoje}
Timezone: ${config.atendimento.timezone}

Regras essenciais:
- Se o cliente quiser agendar, intencao = "AGENDAR".
- Se pedir diferença, preço ou explicação, intencao = "DUVIDA".
- Se pedir humano, dono, atendente ou responsável, intencao = "FALAR_HUMANO".
- Se for assunto fora de estética automotiva, intencao = "FORA_ESCOPO".
- Se o cliente mencionar uma categoria/veículo NÃO atendido, intencao = "CATEGORIA_NAO_ATENDIDA".
- Nunca ofereça categoria com ativo=false.
- Se perguntarem sobre categoria não atendida, responda que no momento não atende essa categoria e cite apenas as categorias ativas.
- Nunca confirme horário.
- Nunca diga que há horário disponível.
- Para agendamento, sempre colete o horário desejado e diga que será verificado com o responsável.
- Preserve dados já existentes no rascunho quando a mensagem atual só complementar.
- Classifique categoria_veiculo pelo modelo/nome do veículo quando possível.
- Exemplos de classificação: Hilux/S10/Ranger/Amarok/Toro = caminhonete; Creta/Compass/HR-V/Tracker = suv; Onix/Gol/HB20/Corolla/Civic/moto = normais; Van/Sprinter/Kombi = utilitarios; caminhão/baú/carreta = carga; Porsche/Mustang/Camaro/BMW M/AMG = esportivos.
- Use apenas estes códigos de categoria se estiverem ativos: ${categoriasAtivas.map(([codigo]) => codigo).join(", ")}.
- Se não souber a categoria do veículo, deixe categoria_veiculo vazio.
- Data sempre DD/MM/AAAA.
- Hora sempre HH:MM.
- Se não souber algum campo, deixe vazio.
- Não invente veículo, categoria, data ou horário.
- resposta_curta deve ser natural, curta e útil, mas SEM confirmar agenda.

Formato obrigatório:
{
  "intencao": "AGENDAR",
  "servico": "",
  "categoria_veiculo": "",
  "veiculo": "",
  "data_desejada": "",
  "hora_desejada": "",
  "resposta_curta": "",
  "confianca": 0.0
}`;

const userPrompt = `Rascunho atual do cliente:
${JSON.stringify(draft, null, 2)}

Mensagem atual:
${incoming.body}

Nome do WhatsApp:
${incoming.pushName || ""}`;

return [{
  json: {
    ...$json,
    openai_body: {
      model: config.openai.model,
      temperature: 0.2,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userPrompt }
      ]
    }
  }
}];

function cleanJsonText(t) {
  return String(t || "").replace(/```json/g, "").replace(/```/g, "").trim();
}

function normalizarTexto(v) {
  return String(v || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s\-\/]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function detectarCategoria(texto, config) {
  const alvo = normalizarTexto(texto);
  if (!alvo) return "";

  const categorias = config.categorias_veiculo || {};
  // Prioridade evita classificar "caminhão baú" como normal por conter palavra genérica.
  const ordemPrioridade = ["carga", "utilitarios", "caminhonete", "esportivos", "suv", "normais"];

  for (const codigo of ordemPrioridade) {
    const cat = categorias[codigo];
    if (!cat) continue;
    const palavras = cat.detector_palavras || [];
    for (const palavra of palavras) {
      const p = normalizarTexto(palavra);
      if (p && alvo.includes(p)) return codigo;
    }
  }

  return "";
}

function normalizarServico(v) {
  const s = normalizarTexto(v);
  if (["1", "simples", "limpeza simples", "lavagem simples", "basica", "básica"].some(x => s.includes(normalizarTexto(x)))) return "simples";
  if (["2", "detalhada", "limpeza detalhada", "higienizacao", "higienização", "completa", "interna completa"].some(x => s.includes(normalizarTexto(x)))) return "detalhada";
  return v || "";
}

const previous = $item(0).$node["12 - Montar Prompt IA"].json;
const config = previous.config;
const content = $json.choices?.[0]?.message?.content || "{}";
let ai = {};

try {
  ai = JSON.parse(cleanJsonText(content));
} catch (e) {
  ai = {
    intencao: "FORA_ESCOPO",
    servico: "",
    veiculo: "",
    categoria_veiculo: "",
    data_desejada: "",
    hora_desejada: "",
    resposta_curta: "Não consegui entender com segurança.",
    confianca: 0
  };
}

ai.intencao = String(ai.intencao || "").toUpperCase().trim() || "AGENDAR";
ai.servico = normalizarServico(ai.servico || previous.draft?.servico || "");
ai.veiculo = ai.veiculo || previous.draft?.veiculo || "";
ai.data_desejada = ai.data_desejada || previous.draft?.data_desejada || "";
ai.hora_desejada = ai.hora_desejada || previous.draft?.hora_desejada || "";

const textoParaDetectar = [ai.categoria_veiculo, ai.veiculo, previous.incoming?.body, previous.draft?.veiculo].filter(Boolean).join(" ");
const categoriaDetectada = detectarCategoria(textoParaDetectar, config);
const categoriaIa = normalizarTexto(ai.categoria_veiculo).replace(/\s+/g, "_");
const categoriaFinal = config.categorias_veiculo?.[categoriaIa] ? categoriaIa : categoriaDetectada;

ai.categoria_veiculo = categoriaFinal || previous.draft?.categoria_veiculo || "";

const cat = config.categorias_veiculo?.[ai.categoria_veiculo];
if (cat && cat.ativo === false) {
  ai.intencao = "CATEGORIA_NAO_ATENDIDA";
}

// Blindagem: se a IA retornou categoria inexistente, zera para pedir esclarecimento em vez de inventar preço.
if (ai.categoria_veiculo && !config.categorias_veiculo?.[ai.categoria_veiculo]) {
  ai.categoria_veiculo = "";
}

return [{ json: { ...previous, ai } }];

const ai = $json.ai || {};
const draft = {
  ...($json.draft || {}),
  ...(ai.servico ? { servico: ai.servico } : {}),
  ...(ai.categoria_veiculo ? { categoria_veiculo: ai.categoria_veiculo } : {}),
  ...(ai.veiculo ? { veiculo: ai.veiculo } : {}),
  ...(ai.data_desejada ? { data_desejada: ai.data_desejada } : {}),
  ...(ai.hora_desejada ? { hora_desejada: ai.hora_desejada } : {})
};

const body = {
  nome: $json.incoming.pushName || $json.cliente?.nome || "",
  draft_servico: draft.servico || null,
  draft_veiculo: draft.veiculo || null,
  draft_data: draft.data_desejada || null,
  draft_hora: draft.hora_desejada || null,
  updated_at: new Date().toISOString()
};

return [{ json: { ...$json, draft, supabase_body: body } }];

const config = $json.config;

function servicoCategoria(cat, servicoCodigo) {
  const base = config.servicos[servicoCodigo] || {};
  const custom = cat.servicos?.[servicoCodigo] || {};
  return { ...base, ...custom };
}

const linhas = Object.entries(config.categorias_veiculo || {})
  .filter(([_, c]) => c.ativo)
  .map(([codigo, c]) => {
    const simples = servicoCategoria(c, "simples");
    const detalhada = servicoCategoria(c, "detalhada");
    return `🚘 ${c.nome}\n• ${simples.nome}: ${simples.preco_texto} | ${simples.tempo_texto}\n• ${detalhada.nome}: ${detalhada.preco_texto} | ${detalhada.tempo_texto}`;
  })
  .join("\n\n");

const text = `Claro. Trabalhamos com estes serviços e categorias:\n\n${linhas}\n\nA limpeza simples é mais rápida, para manutenção.\nA detalhada é mais completa, indicada para sujeira pesada, manchas e acabamento interno.\n\nQual serviço e veículo você quer agendar?`;

return [{ json: { ...$json, destino: "cliente", text } }];

const text = $json.config.atendimento.mensagem_humano;
return [
  { json: { ...$json, destino: "cliente", text } },
  { json: { ...$json, destino: "responsavel", text: `👤 Cliente pediu atendimento humano.\n\nCliente: ${$json.incoming.pushName || "Não informado"}\nWhatsApp: ${$json.incoming.from}\nMensagem: ${$json.incoming.body}` } }
];

const config = $json.config;

function servicoCategoria(cat, servicoCodigo) {
  const base = config.servicos[servicoCodigo] || {};
  const custom = cat.servicos?.[servicoCodigo] || {};
  return { ...base, ...custom };
}

const categorias = Object.entries(config.categorias_veiculo || {})
  .filter(([_, c]) => c.ativo)
  .map(([codigo, c]) => {
    const simples = servicoCategoria(c, "simples");
    const detalhada = servicoCategoria(c, "detalhada");
    return `🚘 ${c.nome}\n1️⃣ ${simples.nome}: ${simples.preco_texto} - ${simples.tempo_texto}\n2️⃣ ${detalhada.nome}: ${detalhada.preco_texto} - ${detalhada.tempo_texto}`;
  })
  .join("\n\n");

const text = `${config.empresa.nome} 🚗✨\n\nVocê quer agendar qual serviço?\n\n${categorias}\n\nMe diga o serviço e o veículo. Exemplo: limpeza detalhada em uma Hilux.`;

return [{ json: { ...$json, destino: "cliente", text } }];

const servico = $json.config.servicos[$json.draft.servico]?.nome || "serviço escolhido";
const categorias = Object.values($json.config.categorias_veiculo || {})
  .filter(c => c.ativo)
  .map(c => `• ${c.nome}: ${c.exemplos}`)
  .join("\n");

const text = `Perfeito. Você escolheu: ${servico}.\n\nQual é o veículo?\n\nAtendemos estas categorias:\n${categorias}\n\nExemplo: Corolla 2020, Hilux, Onix, moto, Creta etc.`;

return [{ json: { ...$json, destino: "cliente", text } }];

const config = $json.config;
const d = $json.draft;
const categoria = config.categorias_veiculo?.[d.categoria_veiculo];
const servicoBase = config.servicos[d.servico] || {};
const servico = categoria?.servicos?.[d.servico] ? { ...servicoBase, ...categoria.servicos[d.servico] } : servicoBase;

const categoriaTexto = categoria?.nome ? `Categoria: ${categoria.nome}\n` : "";
const text = `Show. Para ${servico.nome || "o serviço escolhido"} no veículo ${d.veiculo}, qual dia e horário você prefere?

${categoriaTexto}Valor: ${servico.preco_texto || "a confirmar"}
Tempo estimado: ${servico.tempo_texto || "a confirmar"}

Vou verificar a disponibilidade com o responsável antes de confirmar.

Exemplo:
- amanhã às 14:00
- 10/05 às 09:00`;

return [{ json: { ...$json, destino: "cliente", text } }];

const config = $json.config;
const d = $json.draft;
const categoria = config.categorias_veiculo?.[d.categoria_veiculo];

if (!categoria || categoria.ativo !== true) {
  throw new Error(`Categoria de veículo ausente ou não atendida antes de criar agendamento. categoria_veiculo=${d.categoria_veiculo || "vazia"}`);
}

const servicoBase = config.servicos[d.servico];
const servico = categoria?.servicos?.[d.servico] ? { ...servicoBase, ...categoria.servicos[d.servico] } : servicoBase;

const agendamento = {
  cliente_telefone: $json.incoming.from,
  cliente_nome: $json.incoming.pushName || $json.cliente?.nome || "",
  servico: d.servico,
  servico_nome: servico.nome,
  categoria_veiculo: d.categoria_veiculo,
  categoria_nome: categoria.nome,
  preco: servico.preco,
  preco_texto: servico.preco_texto,
  tempo_texto: servico.tempo_texto,
  veiculo: `${d.veiculo} (${categoria.nome})`,
  data_desejada: d.data_desejada,
  hora_desejada: d.hora_desejada,
  status: "PENDENTE_CONFIRMACAO_RESPONSAVEL",
  lembrete_enviado: false,
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
};

return [{ json: { ...$json, agendamento, supabase_body: [agendamento] } }];

const previous = $item(0).$node["24B - Preparar Criar Agendamento"].json;
const createdResponse = $item(0).$node["25 - Supabase Criar Agendamento"].json;
const created = Array.isArray(createdResponse) ? createdResponse[0] : (createdResponse?.[0] || createdResponse || {});
const config = previous.config;
const ag = { ...previous.agendamento, ...(created || {}) };
const servico = { nome: ag.servico_nome, preco_texto: ag.preco_texto, tempo_texto: ag.tempo_texto };
const agId = ag.id || "ID_NAO_RETORNADO";

function digits(v) {
  return String(v || "").replace(/\D/g, "");
}

function normalizeRows(input) {
  if (Array.isArray(input)) return input;
  if (input && typeof input === "object" && input.id) return [input];
  return [];
}

function minutesFromTime(t) {
  const m = String(t || "").match(/(\d{1,2}):(\d{2})/);
  if (!m) return null;
  return Number(m[1]) * 60 + Number(m[2]);
}

const rowsDoDia = normalizeRows($json).filter(r => String(r.id) !== String(agId));
const horaAtualMin = minutesFromTime(ag.hora_desejada);

const conflitosProximos = rowsDoDia
  .map(r => ({ ...r, diff: horaAtualMin === null || minutesFromTime(r.hora_desejada) === null ? 99999 : Math.abs(minutesFromTime(r.hora_desejada) - horaAtualMin) }))
  .filter(r => r.diff <= 120 || r.status === "CONFIRMADO")
  .sort((a, b) => (minutesFromTime(a.hora_desejada) || 0) - (minutesFromTime(b.hora_desejada) || 0));

let alertaAgenda = "";
if (conflitosProximos.length) {
  const linhas = conflitosProximos.map(r => {
    const nome = r.cliente_nome || "Cliente não informado";
    const veiculo = r.veiculo || "Veículo não informado";
    const servicoNome = r.servico_nome || r.servico || "Serviço não informado";
    const status = String(r.status || "").replace(/_/g, " ");
    const telefone = digits(r.cliente_telefone || "");
    const link = telefone ? `https://wa.me/${telefone}` : "WhatsApp não informado";
    return `• ${r.hora_desejada || "horário não informado"} — ${nome}\n  Veículo: ${veiculo}\n  Serviço: ${servicoNome}\n  Status: ${status}\n  WhatsApp: ${link}`;
  }).join("\n\n");

  alertaAgenda = `\n\n⚠️ ATENÇÃO: Já existe agendamento no mesmo dia ou próximo desse horário:\n\n${linhas}\n\nConfira antes de confirmar o ID ${agId}.`;
}

const clienteText = `${config.atendimento.mensagem_verificar_agenda}\n\nResumo:\nServiço: ${servico.nome}\nVeículo: ${ag.veiculo}\nData desejada: ${ag.data_desejada}\nHorário desejado: ${ag.hora_desejada}\nTempo estimado: ${servico.tempo_texto}\nValor: ${servico.preco_texto}`;

const responsavelText = `🚗 Novo pedido de agendamento - ${config.empresa.nome}\n\nID: ${agId}\nCliente: ${ag.cliente_nome || "Não informado"}\nWhatsApp: ${ag.cliente_telefone}\nVeículo: ${ag.veiculo}\n\nServiço: ${servico.nome}\nValor: ${servico.preco_texto}\nTempo estimado: ${servico.tempo_texto}\n\nData desejada: ${ag.data_desejada}\nHorário desejado: ${ag.hora_desejada}${alertaAgenda}\n\n⚠️ Para evitar conflito quando houver 2 ou mais agendamentos, responda SEMPRE com o ID.\n\nExemplos de confirmação:\nID ${agId} SIM\nID ${agId} OK\nID ${agId} PODE SER\nID ${agId} CONFIRMADO\n\nExemplo para negar e já sugerir nova data/horário:\nID ${agId} NÃO, 10/05 às 16:00`;

return [
  { json: { ...previous, destino: "cliente", text: clienteText, agendamento: ag, conflitos_agenda: conflitosProximos } },
  { json: { ...previous, destino: "responsavel", text: responsavelText, agendamento: ag, conflitos_agenda: conflitosProximos } }
];

return [{
  json: {
    ...$json,
    supabase_body: {
      draft_servico: null,
      draft_veiculo: null,
      draft_data: null,
      draft_hora: null,
      updated_at: new Date().toISOString()
    }
  }
}];

const config = $json.config;
const destino = $json.destino || "cliente";
const chatId = destino === "responsavel" ? config.empresa.telefone_responsavel : $json.incoming.from;

return [{
  json: {
    action: "send",
    waha_base_url: config.empresa.waha_base_url,
    waha_api_key: config.empresa.waha_api_key,
    session: config.empresa.session,
    chatId,
    text: $json.text
  }
}];

const categorias = Object.values($json.config.categorias_veiculo || {})
  .filter(c => c.ativo)
  .map(c => `• ${c.nome} (${c.exemplos})`)
  .join("\n");

const veiculo = $json.draft?.veiculo || $json.ai?.veiculo || "esse tipo de veículo";
const text = `No momento não atendemos ${veiculo} nessa categoria.\n\nCategorias atendidas atualmente:\n${categorias}\n\nSe o seu veículo estiver em uma dessas categorias, me fala o modelo que eu te ajudo com o agendamento.`;

return [{ json: { ...$json, destino: "cliente", text } }];
